// voxel 格式：方块道具目录（几百个模型 × 配色 / 尺寸变体）、方块人（像素脸 + 表情 + 发型 + 帽子 + 服装）、
// "地毯"（一个道具铺成成千上万个，InstancedMesh）。所有模型都是方块拼成的，合并成一个带顶点色的网格。
import * as THREE from "three";
import { mergeGeometries } from "./vendor/BufferGeometryUtils.js";

function rng(seed) {
  let s = (seed >>> 0) || 1;
  return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
}
const pick = (r, a) => a[Math.floor(r() * a.length) % a.length];

// ------------------------------------------------------------------ 方块 → 几何体
// 每个方块：[x, y, z, w, h, d, color]（x/z 是中心，y 是底部）
function geomFromBoxes(boxes) {
  const parts = [];
  const col = new THREE.Color();
  for (const [x, y, z, w, h, d, c] of boxes) {
    if (w <= 0 || h <= 0 || d <= 0) continue;
    const g = new THREE.BoxGeometry(w, h, d).toNonIndexed();
    g.translate(x, y + h / 2, z);
    col.set(c);
    const n = g.attributes.position.count, arr = new Float32Array(n * 3);
    // 顶面略亮、侧面略暗：方块感更强（像参考视频那样的柔和体积光）
    const nrm = g.attributes.normal.array;
    for (let i = 0; i < n; i++) {
      const k = nrm[i * 3 + 1] > 0.5 ? 1.08 : nrm[i * 3 + 1] < -0.5 ? 0.8 : 0.94;
      arr[i * 3] = Math.min(1, col.r * k); arr[i * 3 + 1] = Math.min(1, col.g * k); arr[i * 3 + 2] = Math.min(1, col.b * k);
    }
    g.setAttribute("color", new THREE.BufferAttribute(arr, 3));
    parts.push(g);
  }
  const g = mergeGeometries(parts, false);
  g.computeBoundingBox();
  const bb = g.boundingBox, cx = (bb.min.x + bb.max.x) / 2, cz = (bb.min.z + bb.max.z) / 2;
  g.translate(-cx, -bb.min.y, -cz);
  const size = Math.max(bb.max.x - bb.min.x, bb.max.y - bb.min.y, bb.max.z - bb.min.z) || 1;
  g.scale(1 / size, 1 / size, 1 / size);     // 归一化：最长边 = 1，scale 参数 = 米
  g.computeBoundingBox();
  return g;
}

export const VOX_MAT = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.82, metalness: 0, flatShading: true });

