const quad = (B, a, b, s = 1, neck = 0, tail = true) => {
  B(0,3 * s,0,4 * s,3 * s,7 * s,a);
  for (const [x,z] of [[-1.3,-2.5],[1.3,-2.5],[-1.3,2.5],[1.3,2.5]]) B(x * s,0,z * s,1.2 * s,3 * s,1.2 * s,a);
  B(0,(5 + neck) * s,-4.5 * s,3 * s,3 * s,3 * s,a);
  if (neck) B(0,5 * s,-3.5 * s,1.6 * s,neck * s,1.6 * s,a);
  B(-0.7 * s,(6.2 + neck) * s,-6.05 * s,0.6 * s,0.6 * s,0.1,"#212529"); B(0.7 * s,(6.2 + neck) * s,-6.05 * s,0.6 * s,0.6 * s,0.1,"#212529");
  if (tail) B(0,5 * s,4 * s,0.6 * s,0.6 * s,2 * s,b);
};
