def("bamboo", "nature", "#69db7c", "#2f9e44", (B, a, b) => { for (let i = 0; i < 10; i++) B(0,i * 1.5,0,1,1.4,1,i % 3 ? a : b); B(1,10,0,2,0.4,0.8,b); });
def("autumn_tree", "nature", "#ff922b", "#6b4f3a", (B, a, b) => { B(0,0,0,1.6,5,1.6,b); B(0,5,0,7,4,7,a); B(1,9,0,4,2,4,"#e03131"); });
def("crystal_rock", "nature", "#cc5de8", "#e5dbff", (B, a, b) => { B(0,0,0,6,2,5,"#495057"); B(-1,2,0,1.4,5,1.4,a); B(1,2,1,1.2,3.5,1.2,b); B(0.5,2,-1,1,4,1,a); });
def("sand_castle", "nature", "#e0c181", "#c2a878", (B, a, b) => { B(0,0,0,10,3,10,a); for (const [x,z] of [[-4,-4],[4,-4],[-4,4],[4,4]]) { B(x,3,z,2.4,4,2.4,a); B(x,7,z,2.8,0.6,2.8,b); } B(0,3,0,4,5,4,a); });

// --- 建筑（参数化：每个种子都不一样） ---
const tower = (B, a, b, r, floors, w, d, win = "#a5d8ff") => {
  B(0,0,0,w,floors * 3,d,a);
  for (let f = 0; f < floors; f++) for (let x = -w / 2 + 1; x < w / 2 - 0.5; x += 2) { B(x,f * 3 + 1,-d / 2 - 0.05,1.2,1.4,0.1,r() < 0.75 ? win : "#495057"); B(x,f * 3 + 1,d / 2 + 0.05,1.2,1.4,0.1,win); }
  B(0,floors * 3,0,w + 0.4,0.6,d + 0.4,b);
};
def("house", "building", "#ffe8cc", "#c92a2a", (B, a, b, r) => { B(0,0,0,10,6,8,a); for (let i = 0; i < 4; i++) B(0,6 + i,0,11 - i * 3,1,9,b); B(0,0,-4.01,2,4,0.1,"#8d6e57"); B(-3,2.5,-4.01,2,2,0.1,"#a5d8ff"); B(3,2.5,-4.01,2,2,0.1,"#a5d8ff"); if (r() < 0.5) B(3,8,2,1.4,3,1.4,"#868e96"); });
def("cottage", "building", "#fff3bf", "#6b4f3a", (B, a, b) => { B(0,0,0,8,5,7,a); for (let i = 0; i < 4; i++) B(0,5 + i,0,9 - i * 2.4,1,8,b); B(0,0,-3.51,1.8,3.6,0.1,"#c92a2a"); B(-2.5,2,-3.51,1.6,1.6,0.1,"#a5d8ff"); });
def("cabin", "building", "#8d6e57", "#495057", (B, a, b) => { for (let i = 0; i < 5; i++) B(0,i * 1.2,0,10,1.2,8,i % 2 ? a : "#a0785a"); for (let i = 0; i < 3; i++) B(0,6 + i,0,11 - i * 3.5,1,9,b); B(0,0,-4.01,2,4,0.1,"#5c3a21"); });
def("barn", "building", "#c92a2a", "#f8f9fa", (B, a, b) => { B(0,0,0,12,8,14,a); for (let i = 0; i < 3; i++) B(0,8 + i * 1.5,0,12 - i * 3.6,1.5,14,a); B(0,0,-7.01,6,6,0.1,b); B(0,0,-7.05,6.4,0.4,0.1,b); });
def("apartment", "building", "#ced4da", "#868e96", (B, a, b, r) => tower(B, a, b, r, 6 + Math.floor(r() * 5), 10, 8));
def("skyscraper", "building", "#adb5bd", "#495057", (B, a, b, r) => { const f = 18 + Math.floor(r() * 18); tower(B, a, b, r, f, 8, 8, "#74c0fc"); B(0,f * 3 + 0.6,0,0.4,6,0.4,"#868e96"); });
def("glass_tower", "building", "#74c0fc", "#dee2e6", (B, a, b, r) => { const f = 20 + Math.floor(r() * 15); B(0,0,0,9,f * 3,9,a); for (let k = 0; k < f; k += 2) B(0,k * 3,0,9.1,0.4,9.1,b); B(0,f * 3,0,6,4,6,a); });
def("shop", "building", "#ffe066", "#e03131", (B, a, b) => { B(0,0,0,10,5,7,a); B(0,4,-4,10.4,1,1.6,b); for (let x = -4; x <= 4; x += 2) B(x,4.9,-4.8,1,0.4,0.2,x % 4 ? "#ffffff" : b); B(0,0,-3.51,6,3.6,0.1,"#a5d8ff"); });
def("gas_station", "building", "#f8f9fa", "#e03131", (B, a, b) => { B(0,6,0,14,1,8,b); for (const x of [-5,5]) B(x,0,0,1,6,1,a); B(-2,0,0,1.6,3,1,a); B(2,0,0,1.6,3,1,a); B(0,0,6,8,4,4,a); });
def("school", "building", "#e8590c", "#f8f9fa", (B, a, b, r) => { B(0,0,0,20,8,10,a); for (let x = -8; x <= 8; x += 3) { B(x,1.5,-5.01,2,2,0.1,"#a5d8ff"); B(x,5,-5.01,2,2,0.1,"#a5d8ff"); } B(0,8,0,4,3,4,b); B(0,11,0,0.3,4,0.3,"#495057"); B(1,13.5,0,2,1.4,0.1,"#4dabf7"); });
def("hospital", "building", "#f8f9fa", "#e03131", (B, a, b, r) => { tower(B, a, "#ced4da", r, 6, 14, 10); B(0,10,-5.1,1,4,0.2,b); B(0,11.5,-5.1,4,1,0.2,b); });
def("church", "building", "#f1f3f5", "#868e96", (B, a, b) => { B(0,0,0,8,7,14,a); for (let i = 0; i < 3; i++) B(0,7 + i,0,8 - i * 2.6,1,14,b); B(0,0,-8,4,12,4,a); for (let i = 0; i < 4; i++) B(0,12 + i,-8,4 - i,1,4 - i,b); B(0,16,-8,0.4,3,0.4,"#fab005"); B(0,17.6,-8,1.6,0.4,0.4,"#fab005"); });
def("castle", "building", "#adb5bd", "#868e96", (B, a, b) => { B(0,0,0,16,8,16,a); for (const [x,z] of [[-8,-8],[8,-8],[-8,8],[8,8]]) { B(x,0,z,4,13,4,b); for (let i = 0; i < 4; i++) B(x - 1.5 + i,13,z - 1.5,0.8,1,0.8,b); } B(0,0,-8.01,4,5,0.1,"#5c3a21"); });
def("lighthouse", "building", "#ffffff", "#e03131", (B, a, b) => { for (let i = 0; i < 7; i++) B(0,i * 3,0,5 - i * 0.3,3,5 - i * 0.3,i % 2 ? a : b); B(0,21,0,3,2.4,3,"#fff3bf"); B(0,23.4,0,3.6,1,3.6,b); });
def("windmill", "building", "#f8f9fa", "#a0785a", (B, a, b) => { for (let i = 0; i < 5; i++) B(0,i * 3,0,7 - i,3,7 - i,a); B(0,15,0,3,3,3,b); B(0,16.5,-2,0.6,14,1.2,b); B(0,16.5,-2,14,0.6,1.2,b); });
def("water_tower", "building", "#adb5bd", "#4dabf7", (B, a, b) => { for (const [x,z] of [[-3,-3],[3,-3],[-3,3],[3,3]]) B(x,0,z,0.8,10,0.8,a); B(0,10,0,8,6,8,b); B(0,16,0,6,1,6,b); });
def("tent", "building", "#ff922b", "#212529", (B, a, b) => { for (let i = 0; i < 5; i++) B(0,i * 1.2,0,9 - i * 2,1.2,8,a); B(0,0,-4.01,1.6,2.5,0.1,b); });
