def("pyramid", "building", "#e0c181", "#c2a878", (B, a, b) => { for (let i = 0; i < 10; i++) B(0,i,0,20 - i * 2,1,20 - i * 2,i % 2 ? a : b); });
def("temple", "building", "#f1f3f5", "#ced4da", (B, a, b) => { B(0,0,0,14,1,10,b); for (let x = -6; x <= 6; x += 2.4) { B(x,1,-4,1,7,1,a); B(x,1,4,1,7,1,a); } B(0,8,0,15,1,11,b); for (let i = 0; i < 3; i++) B(0,9 + i,0,15 - i * 5,1,11,a); });
def("stadium", "building", "#ced4da", "#40c057", (B, a, b) => { for (let i = 0; i < 4; i++) { B(0,i * 2,-12 - i,30,2,2,a); B(0,i * 2,12 + i,30,2,2,a); B(-15 - i,i * 2,0,2,2,24,a); B(15 + i,i * 2,0,2,2,24,a); } B(0,0,0,28,0.2,22,b); });
def("factory", "building", "#868e96", "#495057", (B, a, b) => { B(0,0,0,16,7,10,a); for (let i = 0; i < 3; i++) B(-5 + i * 5,7,0,5,2,10,b); B(6,0,3,2,16,2,"#c92a2a"); B(3,0,3,2,13,2,"#c92a2a"); });
def("silo", "building", "#adb5bd", "#c92a2a", (B, a, b) => { B(0,0,0,6,14,6,a); B(0,14,0,5,1.5,5,b); B(0,15.5,0,3,1,3,b); });
def("hut", "building", "#c69c6d", "#e0c181", (B, a, b) => { B(0,0,0,6,4,6,a); for (let i = 0; i < 4; i++) B(0,4 + i,0,8 - i * 2,1,8 - i * 2,b); });
def("treehouse", "building", "#40c057", "#a0785a", (B, a, b) => { B(0,0,0,2,10,2,b); B(0,6,0,7,4,7,"#c69c6d"); for (let i = 0; i < 3; i++) B(0,10 + i,0,8 - i * 2.6,1,8,"#c92a2a"); B(0,12,0,12,5,12,a); });
def("bus_stop", "building", "#4dabf7", "#adb5bd", (B, a, b) => { B(0,7,0,8,0.4,3,a); B(-3.8,0,0,0.4,7,0.4,b); B(3.8,0,0,0.4,7,0.4,b); B(0,0,1.4,8,6,0.2,"#e7f5ff"); B(0,2,0.5,6,0.4,1.2,b); });
