def("ferris_wheel", "building", "#ffffff", "#e03131", (B, a, b) => { for (let i = 0; i < 16; i++) { const an = i / 16 * Math.PI * 2; B(Math.cos(an) * 9,11 + Math.sin(an) * 9,0,1,1,1,a); if (i % 2 === 0) B(Math.cos(an) * 9,10 + Math.sin(an) * 9,0,2,1.6,2,i % 4 ? b : "#4dabf7"); } B(-3,0,0,0.6,12,0.6,a); B(3,0,0,0.6,12,0.6,a); });
