// --- 地标（scale 用真实高度，单位米） ---
def("eiffel_tower", "landmark", "#a0785a", "#8d6e57", (B, a, b) => { for (let i = 0; i < 16; i++) { const w = Math.max(0.6, 12 - i * 0.8); for (const [x,z] of [[-1,-1],[1,-1],[-1,1],[1,1]]) B(x * w / 2,i * 2,z * w / 2,1,2,1,a); if (i === 3 || i === 8) B(0,i * 2,0,w + 1,0.6,w + 1,b); } B(0,32,0,0.6,4,0.6,b); });
def("statue_of_liberty", "landmark", "#63b38f", "#adb5bd", (B, a, b) => { B(0,0,0,10,10,10,b); B(0,10,0,6,4,6,b); B(0,14,0,3,8,2.4,a); B(0,22,0,2.2,2.2,2.2,a); for (let i = -2; i <= 2; i++) B(i * 0.5,24.2,0,0.4,1,0.4,a); B(2,19,0,0.8,6,0.8,a); B(2,25,0,1.2,1.4,1.2,"#ffd43b"); B(-1.6,18,-0.6,0.8,2,1.4,a); });
def("burj_khalifa", "landmark", "#ced4da", "#adb5bd", (B, a, b) => { const steps = [[8,10],[6.5,10],[5,10],[4,8],[3,8],[2,6],[1.2,6],[0.6,6],[0.3,8]]; let y = 0; for (const [w,h] of steps) { B(0,y,0,w,h,w,a); B(w / 3,y,0,w / 2,h * 0.7,w / 2,b); y += h; } });
def("big_ben", "landmark", "#c2a878", "#2b3a55", (B, a, b) => { B(0,0,0,5,22,5,a); B(0,22,0,6,5,6,a); B(0,23,-3.01,4,4,0.1,"#fff9db"); B(0,27,0,5,2,5,b); for (let i = 0; i < 4; i++) B(0,29 + i,0,4 - i,1,4 - i,b); });
def("great_pyramid", "landmark", "#e0c181", "#c2a878", (B, a, b) => { for (let i = 0; i < 14; i++) B(0,i,0,28 - i * 2,1,28 - i * 2,i % 2 ? a : b); });
def("empire_state", "landmark", "#adb5bd", "#868e96", (B, a, b) => { B(0,0,0,10,20,8,a); B(0,20,0,7,8,6,a); B(0,28,0,5,6,4,a); B(0,34,0,3,3,3,b); B(0,37,0,1,3,1,b); B(0,40,0,0.4,4,0.4,b); });
def("leaning_tower", "landmark", "#f8f9fa", "#ced4da", (B, a, b) => { for (let i = 0; i < 8; i++) B(i * 0.35,i * 2.5,0,5,2.5,5,i % 2 ? a : b); B(2.8,20,0,3.6,2,3.6,a); });
def("space_needle", "landmark", "#f8f9fa", "#fab005", (B, a, b) => { B(0,0,0,4,1,4,a); B(0,1,0,1.4,22,1.4,a); B(0,23,0,8,1.4,8,b); B(0,24.4,0,6,1,6,a); B(0,25.4,0,0.4,5,0.4,a); });
def("taj_mahal", "landmark", "#f8f9fa", "#e9ecef", (B, a, b) => { B(0,0,0,24,2,24,b); B(0,2,0,14,8,14,a); for (let i = 0; i < 4; i++) B(0,10 + i * 1.4,0,9 - i * 2,1.4,9 - i * 2,a); B(0,15.6,0,0.6,2,0.6,"#fab005"); for (const [x,z] of [[-11,-11],[11,-11],[-11,11],[11,11]]) B(x,2,z,1.4,14,1.4,a); });
def("colosseum", "landmark", "#e0c181", "#c2a878", (B, a, b) => { for (let i = 0; i < 24; i++) { const an = i / 24 * Math.PI * 2; B(Math.cos(an) * 12,0,Math.sin(an) * 9,3,i % 3 ? 10 : 7,3,i % 2 ? a : b); } });
