def("stonehenge", "landmark", "#868e96", "#adb5bd", (B, a, b) => { for (let i = 0; i < 10; i++) { const an = i / 10 * Math.PI * 2; B(Math.cos(an) * 8,0,Math.sin(an) * 8,2,6,1.4,a); if (i % 2 === 0) B(Math.cos(an + 0.3) * 8,6,Math.sin(an + 0.3) * 8,4,1,1.4,b); } });

